update arcgms a set a.tipo_gasto = 'PROD', a.`permiso_inv` = 'S'
where a.`cuenta` in (
5330020100,5330020200,5330020300,5330030100,5330030200,5330030300,5330100100,5330100200,5330100300,5330120100
);

